/**
 * eagle-bridge-fixtures.integration.test.js
 *
 * Real-file integration tests for the eagle_bridge deterministic tracing path.
 * Uses actual PNG/WebP/JPEG images generated by the eagle-metadata-bridge ComfyUI
 * custom node to verify the full binary-extraction → parsing → tag/annotation pipeline.
 *
 * Fixture files: tests/fixtures/bridge-*.{png,webp,jpg}
 *
 * To add a new fixture:
 *   1. Generate an image via ComfyUI with eagle-metadata-bridge node
 *   2. Copy the PNG/WebP to tests/fixtures/bridge-<name>.{png,webp}
 *   3. Add a test case to TEST_CASES below (with expected tags/annotation)
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const MetadataService = require('../../js/metadata-parser/integration/MetadataService.js');
const TagGenerator = require('../../js/metadata-processor/TagGenerator.js');
const AnnotationBuilder = require('../../js/metadata-processor/AnnotationBuilder.js');

const ROOT = process.cwd();

function readFixture(relativePath) {
  const full = join(ROOT, relativePath);
  if (!existsSync(full)) return null;
  return new Uint8Array(readFileSync(full));
}

// All options enabled
const ALL_SETTINGS = {
  checkpoint: true, lora: true, positive: true, negative: true,
  seed: true, steps: true, cfg: true, sampler: true, scheduler: true,
  includeAllSamplers: false,
};

function t(key) {
  const map = {
    'ui.option.checkpoint': 'Checkpoint', 'ui.option.lora': 'LoRA',
    'ui.option.seed': 'Seed', 'ui.option.steps': 'Steps', 'ui.option.sampler': 'Sampler',
  };
  return map[key] || key.split('.').pop();
}

// ---------------------------------------------------------------------------
// Test cases – expected tags (sorted) and annotation are hand-written ground truth
// ---------------------------------------------------------------------------
