// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------
describe('eagle_bridge real-fixture integration tests', () => {
  let service;

  beforeAll(() => {
    service = new MetadataService();
  });

  TEST_CASES.forEach(({ name, label, fixtures, expectedTags, expectedAnnotation }) => {
    fixtures.forEach(({ file, mimeType }) => {
      const fmt = mimeType.split('/')[1].toUpperCase();
      describe(`${name} (${label}) ${fmt}`, () => {

        it('fixture file exists', () => {
          expect(existsSync(join(ROOT, file))).toBe(true);
        });

        it('eagle_bridge chunk is present in fixture', () => {
          const buffer = readFixture(file);
          if (!buffer) return;
          const results = service.extractMetadata(buffer, mimeType);
          const comfy = results.find(r => r.format === 'comfyui');
          expect(comfy).toBeDefined();
          expect(comfy.sampler_fallback).toBe(false);
        });

        it('extracts comfyui format without error', () => {
          const buffer = readFixture(file);
          if (!buffer) return;
          expect(() => service.extractMetadata(buffer, mimeType)).not.toThrow();
          const results = service.extractMetadata(buffer, mimeType);
          expect(results.find(r => r.format === 'comfyui')).toBeDefined();
        });

        it('has at least one generation step', () => {
          const buffer = readFixture(file);
          if (!buffer) return;
          const results = service.extractMetadata(buffer, mimeType);
          const comfy = results.find(r => r.format === 'comfyui');
          expect(comfy?.generationSteps?.length).toBeGreaterThan(0);
        });

        it('deterministic mode: is not sampler_fallback', () => {
          const buffer = readFixture(file);
          if (!buffer) return;
          const results = service.extractMetadata(buffer, mimeType);
          const comfy = results.find(r => r.format === 'comfyui');
          expect(comfy?.sampler_fallback).toBe(false);
        });

        it('tags match expected', () => {
          const buffer = readFixture(file);
          if (!buffer) return;
          const results = service.extractMetadata(buffer, mimeType);
          const comfy = results.find(r => r.format === 'comfyui');
          if (!comfy) return;
          const { tags } = TagGenerator.generate(comfy, ALL_SETTINGS);
          expect([...tags].sort()).toEqual(expectedTags);
        });

        it('annotation matches expected', () => {
          const buffer = readFixture(file);
          if (!buffer) return;
          const results = service.extractMetadata(buffer, mimeType);
          const comfy = results.find(r => r.format === 'comfyui');
          if (!comfy) return;
          const annotation = AnnotationBuilder.build(comfy, ALL_SETTINGS, t);
          expect(annotation).toBe(expectedAnnotation);
        });
      });
    });
  });
});
